/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::ALREADY_CLAIMED,
    error_codes::HANDLE_NOT_FOUND,
    error_codes::HANDLE_EXPIRED,
    error_codes::KEY_UNSUPPORTED,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `provision/vta/claim:alreadyClaimed`
    ///
    /// The handle has already been claimed by another key (VTI-LNK-114). Carries no details, so a second scanner learns nothing about the first.
    ///
    /// Declared `retryable: false`.
    pub const ALREADY_CLAIMED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "provision/vta/claim:alreadyClaimed",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `provision/vta/claim:handleNotFound`
    ///
    /// No reservation has this handle.
    ///
    /// Declared `retryable: false`.
    pub const HANDLE_NOT_FOUND: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "provision/vta/claim:handleNotFound",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `provision/vta/claim:handleExpired`
    ///
    /// The handle's window (the link's `_exp`) has passed, or the reservation has otherwise ended.
    ///
    /// Declared `retryable: false`.
    pub const HANDLE_EXPIRED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "provision/vta/claim:handleExpired",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `provision/vta/claim:keyUnsupported`
    ///
    /// The document's issuer is not an Ed25519 `did:key`.
    ///
    /// Declared `retryable: false`.
    pub const KEY_UNSUPPORTED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "provision/vta/claim:keyUnsupported",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
}
